import re
from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    negative = False

    # Handle parentheses sign: '(R$ 5,00)'
    if s.startswith('(') and s.endswith(')'):
        negative = True
        s = s[1:-1]

    # Handle leading minus sign
    if s.startswith('-'):
        negative = True
        s = s[1:]

    # Remove optional 'R$' prefix (possibly followed by spaces)
    s = re.sub(r'^R\$[ ]*?', '', s, count=1)

    # Remove all spaces
    s = s.replace(' ', '')

    if not s:
        raise ValueError("empty string")

    # Split integer part and cents part on comma
    if ',' in s:
        int_part, cents_part = s.split(',', 1)
        if len(cents_part) != 2 or not cents_part.isdigit():
            raise ValueError("cents must be exactly 2 digits after comma")
    else:
        int_part, cents_part = s, ''

    # Validate and normalize integer part: either plain digits or groups of exactly 3
    if not re.fullmatch(r'\d+', int_part):
        raise ValueError("integer part must be plain digits or groups of exactly 3 digits")

    if '.' in int_part:
        groups = int_part.split('.')
        if len(groups) != 2:
            raise ValueError("integer part must have at most one '.' separating two groups")
        int_groups = groups[0]
        if len(int_groups) % 3 != 0:
            raise ValueError("thousands groups must have length divisible by 3")
        for g in int_groups.split('.'):
            if len(g) % 3 != 0:
                raise ValueError("thousands groups must have length divisible by 3")
        int_value = int(int_groups.replace('.', ''))
    else:
        int_value = int(int_part)

    # Build the numeric string: integer part + '.' + cents part
    if cents_part:
        numeric_str = f"{int_value}.{cents_part}"
    else:
        numeric_str = str(int_value)

    result = Decimal(numeric_str)
    if negative:
        result = -result
    return result
