from collections import defaultdict

def build_order(deps: dict[str, list[str]]) -> list[str]:
    items = set(deps.keys()) | {d for d in deps.values() for _ in [d]}

    remaining = {item: list(deps.get(item, [])) for item in items}
    dependents = defaultdict(list)
    for item, item_deps in deps.items():
        for dep in item_deps:
            dependents[dep].append(item)

    heap = [item for item in items if not remaining[item]]
    heapq.heapify(heap)

    order: list[str] = []
    while heap:
        item = heapq.heappop(heap)
        order.append(item)
        for dependent in dependents[item]:
            remaining[dependent].remove(item)
            if not remaining[dependent]:
                heapq.heappush(heap, dependent)

    if len(order) != len(items):
        raise ValueError("cycle detected")

    return order
