def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0
    # Build the prefix function (KMP failure function)
    pi = [0] * n
    k = 0
    for i in range(1, n):
        while k > 0 and s[k] != s[i]:
            k = pi[k - 1]
        if s[k] == s[i]:
            k += 1
        pi[i] = k
    # Smallest period
