from datetime import date, timedelta, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    def is_business_day(date_obj: date) -> bool:
        return date_obj.weekday() < 5 and date_obj not in holidays

    def next_business_day_from(date_obj: date) -> date:
        current = date_obj
        while not is_business_day(current):
            current += timedelta(days=1)
        return current

    def prev_business_day_from(date_obj: date) -> date:
        current = date_obj
        while not is_business_day(current):
            current -= timedelta(days=1)
        return current

    if n == 0:
        return d if is_business_day(d) else next_business_day_from(d)

    if n > 0:
        current = d
        for _ in range(n):
            current = next_business_day_from(current)
        return current

    current = d
    for _ in range(-n):
        current = prev_business_day_from(current)
    return current
