def build_order(deps: dict[str, list[str]]) -> list[str]:
    graph: dict[str, list[str]] = {}
    in_degree: dict[str, int] = {}

    all_items: set[str] = set()
    for item, item_deps in deps.items():
        all_items.add(item)
        for d in item_deps:
            all_items.add(d)

    for item in all_items:
        in_degree.setdefault(item, 0)

    for item, item_deps in deps.items():
        for d in item_deps:
            graph.setdefault(d, []).append(item)
            in_degree[item] += 1

    heap = [item for item in all_items if in_degree[item] == 0]
    heapq.heapify(heap)

    order: list[str] = []
    while heap:
        item = heapq.heappop(heap)
        order.append(item)
        for dependent in sorted(graph.get(item, [])):
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(order) != len(all_items):
        raise ValueError("cycle detected")

    return order
