def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must not be negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not contain negative values")
    if sum(weights) == 0:
        raise ValueError("weights must not all be zero")

    total = sum(weights)
    parts = [total_cents * w // total for w in weights]
    remainders = [total_cents * w - p * total for w, p in zip(weights, parts)]
    parts[0] += 1
    for i in range(1, len(parts)):
        if remainders[i] > remainders[i - 1]:
            parts[i] += 1
            remainders[i - 1] = remainders[i]
    return parts
