from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    if n == 0:
        # Return d if it is a business day, otherwise the next business day.
        if is_business_day(d, holidays):
            return d
        return next_business_day(d, holidays)

    step = d + timedelta(days=1) if n > 0 else d - timedelta(days=1)
    if n > 0:
        count = 0
        while count < n:
            if is_business_day(step, holidays):
                count += 1
                d = step
            step += timedelta(days=1)
        return d
    else:
        count = 0
        while count < -n:
            if is_business_day(step, holidays):
                count += 1
                d = step
            step -= timedelta(days=1)
        return d


def is_business_day(d: date, holidays: set[date]) -> bool:
    return d.weekday() < 5 and d not in holidays


def next_business_day(d: date, holidays: set[date]) -> date:
    step = d + timedelta(days=1)
    while not is_business_day(step, holidays):
        step += timedelta(days=1)
    return step
