import re

_VERSION_RE = re.compile(r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$')

def compare_versions(a: str, b: str) -> int:
    ma, mi, pa, pre_a, build_a = _VERSION_RE.match(a).groups()
    mb, mb2, pb, pre_b, build_b = _VERSION_RE.match(b).groups()

    for x, y in ((int(ma), int(mb)), (int(mi), int(mb2)), (int(pa), int(pb))):
        if x != y:
            return -1 if x < y else 1

    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    return _compare_pre(pre_a, pre_b)

def _compare_pre(pre_a: str, pre_b: str) -> int:
    ids_a = pre_a.split('.')
    ids_b = pre_b.split('.')

    for x, y in zip(ids_a, ids_b):
        if x.isdigit() and y.isdigit():
            x, y = int(x), int(y)
            if x != y:
                return -1 if x < y else 1
            continue
        if x.isdigit() != y.isdigit():
            return -1 if x.isdigit() else 1
        if x != y:
            return -1 if x < y else 1

    if len(ids_a) == len(ids_b):
        return 0
    return -1 if len(ids_a) < len(ids_b) else 1
