from collections import defaultdict, deque

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Nodes that appear only as dependencies must be included with no outgoing deps.
    all_items = set(deps.keys())
    for u in deps:
        all_items.update(deps[u])

    # remaining[u] = number of dependencies of u not yet placed
    remaining = {u: len(deps.get(u, [])) for u in all_items}

    # dependents[v] = items that depend on v (so v must come before them)
    dependents = defaultdict(list)
    for u in deps:
        for v in deps[u]:
            dependents[v].append(u)

    # Ready set of items with all dependencies satisfied.
    ready = [u for u in all_items if remaining[u] == 0]
    order: list[str] = []

    while ready:
        ready.sort()
        u = ready.pop(0)
        order.append(u)
        for w in dependents[u]:
            remaining[w] -= 1
            if remaining[w] == 0:
                ready.append(w)

    if len(order) != len(all_items):
        raise ValueError("cycle detected")

    return order
