import functools

def natural_sorted(names: list[str]) -> list[str]:
    def tokenize(s: str):
        tokens: list[tuple[bool, str]] = []  # (is_digit, text)
        i = 0
        while i < len(s):
            if s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append((True, int(s[i:j])))
                i = j
            else:
                j = i
                while j < len(s) and not s[j].isdigit():
                    j += 1
                tokens.append((False, s[i:j].lower()))
                i = j
        return tokens

    def compare(a: str, b: str) -> int:
        ta = tokenize(a)
        tb = tokenize(b)
        for x, y in zip(ta, tb):
            if x[0] != y[0]:
                # digit run vs non-digit run: treat digit as "less"
                return -1 if x[0] else 1
            if x[0] and y[0]:
                if x[1] != y[1]:
                    return -1 if x[1] < y[1] else 1
            else:
                if x[1] != y[1]:
                    return -1 if x[1] < y[1] else 1
        # shorter token list is the prefix (smaller)
        return -1 if len(ta) < len(tb) else 1 if len(ta) > len(tb) else 0

    return sorted(names, key=functools.cmp_to_key(compare))
